class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for a, b, w in edges:
            g[a].append((b, w)); g[b].append((a, w))
        def dfs(u, p, d):
            c = 1 if d % signalSpeed == 0 else 0
            for v, w in g[u]:
                if v != p: c += dfs(v, u, d + w)
            return c
        res = []
        for c in range(n):
            tot = prev = 0
            for v, w in g[c]:
                k = dfs(v, c, w)
                tot += prev * k
                prev += k
            res.append(tot)
        return res

