class Solution {
public:
    vector<int> countPairsOfConnectableServers(vector<vector<int>>& edges, int signalSpeed) {
        int n = edges.size() + 1;
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
        }
        function<int(int,int,long long)> dfs = [&](int u, int p, long long d) -> int {
            int c = d % signalSpeed == 0;
            for (auto& [v, w] : g[u])
                if (v != p) c += dfs(v, u, d + w);
            return c;
        };
        vector<int> res(n);
        for (int c = 0; c < n; c++) {
            long long tot = 0; int prev = 0;
            for (auto& [v, w] : g[c]) {
                int k = dfs(v, c, w);
                tot += (long long)prev * k;
                prev += k;
            }
            res[c] = tot;
        }
        return res;
    }
};

