class Solution {
    private int speed;
    private List<List<int[]>> g;
    private int dfs(int u, int p, long d) {
        int c = (d % speed == 0) ? 1 : 0;
        for (int[] e : g.get(u))
            if (e[0] != p) c += dfs(e[0], u, d + e[1]);
        return c;
    }
    public int[] countPairsOfConnectableServers(int[][] edges, int signalSpeed) {
        speed = signalSpeed;
        int n = edges.length + 1;
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(new int[]{e[1], e[2]});
            g.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] res = new int[n];
        for (int c = 0; c < n; c++) {
            long tot = 0; int prev = 0;
            for (int[] e : g.get(c)) {
                int k = dfs(e[0], c, e[1]);
                tot += (long) prev * k;
                prev += k;
            }
            res[c] = (int) tot;
        }
        return res;
    }
}

