var countPairsOfConnectableServers = function(edges, signalSpeed) {
    const n = edges.length + 1;
    const g = Array.from({length: n}, () => []);
    for (const [a, b, w] of edges) { g[a].push([b, w]); g[b].push([a, w]); }
    const dfs = (u, p, d) => {
        let c = d % signalSpeed === 0 ? 1 : 0;
        for (const [v, w] of g[u]) if (v !== p) c += dfs(v, u, d + w);
        return c;
    };
    const res = [];
    for (let c = 0; c < n; c++) {
        let tot = 0, prev = 0;
        for (const [v, w] of g[c]) {
            const k = dfs(v, c, w);
            tot += prev * k;
            prev += k;
        }
        res.push(tot);
    }
    return res;
};
